def run(Ename,nE,Tname,nT,Mex,nM,trials=25):
    best=(1e9,None)
    for s in range(trials):
        rs=np.random.RandomState(s)
        q0=rs.uniform(-1.5,1.5,nE+nT+nM)
        def res(q):
            cols=[np.sqrt(t), E[Ename](q[:nE])*(1 if True else 1)]
            cols=[np.sqrt(t), E[Ename](q[:nE]), Mex(q[nE:nE+nM])*TT[Tname][0](q[nE+nM:])] if nT>0 else None
            A=np.column_stack(cols)
            c,*_=np.linalg.lstsq(A,sigma,rcond=None)
            return A@c-sigma
        try:
            r=least_squares(lambda q: np.nan_to_num(res(q),nan=1e3,posinf=1e3,neginf=-1e3),q0)
            v=np.mean(r.fun**2)/np.var(sigma)
            if v<best[0]: best=(v,r.x)
        except Exception: pass
    return best
